# -*- coding: utf-8 -*-
# Задание №4: эталонное решение (перебор слов product('01', repeat=L) + проверка условия Фано).
# Запуск: python solve.py запрос.json   (формат запроса — см. tests/*.json)
import sys, json, heapq
from itertools import product, combinations
from collections import Counter


def fano_ok(words, rev=False):
    """Ни одно слово не является началом (rev=True: окончанием) другого; одинаковые слова недопустимы."""
    n = len(words)
    for i in range(n):
        for j in range(n):
            if i != j and (words[j].endswith(words[i]) if rev else words[j].startswith(words[i])):
                return False
    return True


def words_of_len(L):
    return ["".join(t) for t in product("01", repeat=L)]          # по возрастанию числового значения


def main():
    q = json.load(open(sys.argv[1], encoding="utf-8"))
    k = q["kind"]
    known = q.get("known", {})
    fixed = list(known.values())
    rev = (k == "rev_word")
    if k in ("one_word", "rev_word"):
        for L in range(1, 12):
            f = [w for w in words_of_len(L) if fano_ok(fixed + [w], rev)]
            if f:
                print(f[0])
                return
    elif k == "sum_two":
        free = []
        for L in range(1, 8):
            free += [w for w in words_of_len(L) if fano_ok(fixed + [w])]
        best = min(sum(map(len, c)) for c in combinations(free, q["k"]) if fano_ok(list(c)))
        print(best)
    elif k == "equal_len":
        for L in range(1, 12):
            f = [w for w in words_of_len(L) if fano_ok(fixed + [w])]
            if len(f) >= q["k"]:
                print(sum(map(len, fixed)) + q["k"] * L)
                return
    elif k == "shorten":
        for ch, w in known.items():
            new = dict(known)
            new[ch] = w[:-1]
            if len(w) > 1 and fano_ok(list(new.values())):
                print(ch + w[:-1])
    elif k == "decode":
        inv = {w: ch for ch, w in known.items()}
        out, cur = "", ""
        for b in q["bits"]:
            cur += b
            if cur in inv:
                out += inv[cur]
                cur = ""
        print(out)
    elif k == "huffman":
        h = list(Counter(q["word"]).values())
        heapq.heapify(h)
        tot = 0
        while len(h) > 1:
            a, b = heapq.heappop(h), heapq.heappop(h)
            tot += a + b
            heapq.heappush(h, a + b)
        print(tot)


main()

